CREATE OR REPLACE FUNCTION fvoci.app_restore_batch(p_batch uuid, p_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'fvoci', 'pg_temp'
AS $function$
  DECLARE
    v_batch trash_batches%ROWTYPE;
    v_doc   documents%ROWTYPE;
    v_item  uuid;
